const job = $('Lock DI Job').first().json || {};
const rawProject = $('Fetch DI Project Context').first().json;
const project = Array.isArray(rawProject) ? rawProject[0] : rawProject;
const qaJobs = $items('Fetch Read Only QA Context').map(i => i.json).filter(j => j && j.job_id);
const input = job.input || {};
const submitted = input.extraction || input.intelligence || input.payload || {};
const contextText = [project?.name, project?.description, JSON.stringify(project?.tags || []), JSON.stringify(input), ...qaJobs.map(j => JSON.stringify({ input: j.input, output: j.output }).slice(0, 4000))].join('\n');
const techCatalog = [['React','frontend'], ['Next.js','frontend'], ['Angular','frontend'], ['Vue','frontend'], ['TypeScript','language'], ['JavaScript','language'], ['Java','language'], ['Spring Boot','backend'], ['Node.js','backend'], ['Express','backend'], ['Python','language'], ['FastAPI','backend'], ['PostgreSQL','database'], ['Supabase','database'], ['MongoDB','database'], ['Redis','cache'], ['Kafka','messaging'], ['RabbitMQ','messaging'], ['Docker','devops'], ['Kubernetes','devops'], ['Jenkins','devops'], ['GitHub Actions','devops'], ['Jira','delivery'], ['Confluence','knowledge'], ['ChromaDB','vector'], ['OpenAI','ai'], ['Azure OpenAI','ai'], ['Playwright','qa'], ['Selenium','qa'], ['Cypress','qa'], ['REST API','integration'], ['GraphQL','integration']];
const explicitTechs = Array.isArray(submitted.technologies) ? submitted.technologies : Array.isArray(input.technologies) ? input.technologies : [];
const foundTechs = techCatalog.filter(([name]) => new RegExp('\\b' + name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i').test(contextText)).map(([name, category]) => ({ name, category, confidenceScore: 0.72, sourceType: 'context_scan', sourceRef: job.job_id }));
const techMap = new Map();
for (const t of [...foundTechs, ...explicitTechs]) { const name = String(t.name || t.technology || t).trim(); if (!name) continue; const normalized = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, ''); techMap.set(normalized, { name, normalizedName: normalized, category: t.category || 'detected', description: t.description || null, vendor: t.vendor || null, version: t.version || null, tags: Array.isArray(t.tags) ? t.tags : [], confidenceScore: Number(t.confidenceScore || t.confidence_score || 0.7), sourceType: t.sourceType || 'di_worker', sourceRef: t.sourceRef || job.job_id }); }
const technologies = [...techMap.values()];
const explicitSolutions = Array.isArray(submitted.solutions) ? submitted.solutions : Array.isArray(input.solutions) ? input.solutions : [];
const solutions = explicitSolutions.map((s, index) => ({ title: s.title || `${project?.name || job.project_id} reusable delivery pattern ${index + 1}`, slug: s.slug, summary: s.summary || s.description || 'Reusable delivery intelligence candidate extracted from project artifacts.', problemStatement: s.problemStatement || s.problem_statement || null, implementationApproach: s.implementationApproach || s.implementation_approach || null, qaApproach: s.qaApproach || s.qa_approach || null, riskFactors: Array.isArray(s.riskFactors) ? s.riskFactors : [], productionLearnings: Array.isArray(s.productionLearnings) ? s.productionLearnings : [], implementationComplexity: s.implementationComplexity || s.complexity || 'medium', applicabilityTags: Array.isArray(s.applicabilityTags) ? s.applicabilityTags : (project?.tags || []), visibilityLevel: s.visibilityLevel || 'project', ownerTeam: s.ownerTeam || project?.owner || null, aiSummary: s.aiSummary || s.summary || null, status: s.status || 'draft', technologies: Array.isArray(s.technologies) ? s.technologies : technologies.slice(0, 5).map(t => t.name), assets: Array.isArray(s.assets) ? s.assets : [{ assetType: 'project_context', title: project?.name || job.project_id, description: 'Source project context used during DI extraction', visibilityLevel: s.visibilityLevel || 'project' }] }));
if (solutions.length === 0 && ['solution_extract','project_intelligence_extract'].includes(job.job_type) && qaJobs.length > 0) solutions.push({ title: `${project?.name || job.project_id} QA delivery intelligence pattern`, summary: 'Draft reusable solution candidate based on completed QA generation outputs and project context.', problemStatement: 'Project delivery and QA knowledge may be reusable across similar initiatives.', implementationApproach: 'Review generated QA assets, project metadata, and extracted technologies before publishing.', qaApproach: 'Reuse proven QA planning, risk, traceability, and test design outputs where applicable.', riskFactors: ['Requires human review before organization-wide reuse'], productionLearnings: [], implementationComplexity: 'medium', applicabilityTags: project?.tags || [], visibilityLevel: 'project', status: 'draft', technologies: technologies.slice(0, 5).map(t => t.name), assets: qaJobs.slice(0, 3).map(j => ({ assetType: 'qa_job', title: `QA output ${j.job_id}`, description: 'Existing QA generation output used as reusable evidence', visibilityLevel: 'project' })) });
const explicitLearnings = Array.isArray(submitted.learnings) ? submitted.learnings : Array.isArray(input.learnings) ? input.learnings : [];
const learnings = explicitLearnings.map(l => ({ title: l.title || 'Delivery learning', category: l.category || 'delivery', learningSummary: l.learningSummary || l.summary || l.description || '', impactLevel: l.impactLevel || 'medium', reusableRecommendation: l.reusableRecommendation || l.recommendation || '', visibilityLevel: l.visibilityLevel || 'project', sourceRef: l.sourceRef || job.job_id }));
if (learnings.length === 0 && technologies.length > 0) learnings.push({ title: `${project?.name || job.project_id} technology footprint captured`, category: 'technology', learningSummary: `Detected ${technologies.length} technologies for reuse and discovery.`, impactLevel: 'medium', reusableRecommendation: 'Review technology patterns for cross-project standardization opportunities.', visibilityLevel: 'project', sourceRef: job.job_id });
const relationships = [];
for (const t of technologies) relationships.push({ sourceEntityType: 'project', sourceEntityId: job.project_id, targetEntityType: 'technology', targetEntityId: t.normalizedName, relationshipType: 'uses_technology', confidenceScore: t.confidenceScore || 0.7, evidence: [{ source: 'di_worker', jobId: job.job_id }], visibilityLevel: 'project' });
for (const s of solutions) relationships.push({ sourceEntityType: 'project', sourceEntityId: job.project_id, targetEntityType: 'reusable_solution', targetEntityId: s.slug || s.title, relationshipType: 'has_reusable_candidate', confidenceScore: 0.72, evidence: [{ source: 'di_worker', jobId: job.job_id }], visibilityLevel: s.visibilityLevel || 'project' });
const explicitRecommendations = Array.isArray(submitted.recommendations) ? submitted.recommendations : Array.isArray(input.recommendations) ? input.recommendations : [];
const recommendations = explicitRecommendations.map(r => ({ recommendationType: r.recommendationType || r.type || 'delivery_intelligence', title: r.title || 'Delivery intelligence recommendation', summary: r.summary || '', rationale: r.rationale || '', relatedEntityType: r.relatedEntityType || null, relatedEntityId: r.relatedEntityId || null, confidenceScore: r.confidenceScore || 0.7, status: 'new' }));
if (recommendations.length === 0 && solutions.length > 0) recommendations.push({ recommendationType: 'reusable_accelerator_available', title: 'Review reusable solution candidate', summary: `${solutions.length} reusable solution candidate(s) were extracted for this project.`, rationale: 'Draft candidates should be reviewed, sanitized, and published if suitable for reuse.', relatedEntityType: 'project', relatedEntityId: job.project_id, confidenceScore: 0.74, status: 'new' });
const payload = { jobId: job.job_id, jobType: job.job_type, projectId: job.project_id, requestedBy: job.requested_by, technologies, solutions, learnings, relationships, recommendations };
const totalRecords = technologies.length + solutions.length + learnings.length + relationships.length + recommendations.length;
return [{ json: { jobId: job.job_id, projectId: job.project_id, requestedBy: job.requested_by, jobType: job.job_type, startedAt: job.output?.startedAt || new Date().toISOString(), payload, extractionSummary: { technologies: technologies.length, solutions: solutions.length, learnings: learnings.length, relationships: relationships.length, recommendations: recommendations.length, totalRecords, qaContextJobs: qaJobs.length, projectName: project?.name || null }, warning: totalRecords === 0 ? 'No Delivery Intelligence records were extracted from this job input/context.' : null } }];

const built = $('Build DI Extraction Payload').first().json;
const persisted = $json || {};
const counts = persisted.counts || {};
const warning = built.warning || (Object.values(counts).reduce((sum, v) => sum + Number(v || 0), 0) === 0 ? 'No DI records were persisted.' : null);
return [{ json: { jobId: built.jobId, status: warning ? 'completed_with_warnings' : 'completed', output: { ok: true, jobType: built.jobType, projectId: built.projectId, extractionSummary: built.extractionSummary, persistResult: persisted, warning, completedAt: new Date().toISOString() } } }];

const built = $('Build DI Extraction Payload').first().json;
const message = $json.error?.message || $json.message || 'Delivery Intelligence persistence failed';
return [{ json: { jobId: built.jobId, output: { ok: false, jobType: built.jobType, projectId: built.projectId, extractionSummary: built.extractionSummary, error: message, failedAt: new Date().toISOString() }, error: message } }];
